for w in writes:
    if isinstance(w, dict) and w.get("applied") is False:
        continue
    if not isinstance(w, dict):
        continue
    action = w.get("action") or w.get("op") or w.get("name") or ""
    args = w.get("args") if isinstance(w.get("args"), dict) else w

    # PDF files are treated as extracted text; only clearly determined line/cell/text writes apply.
    # Support generic whole-file overwrite/create style writes if explicitly present.
    if action in ("write_file", "create_file", "create_new_file", "overwrite_file"):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            content = args.get("content")
            if content is not None:
                text = str(content)
    elif action in ("append_to_file", "write_to_file", "append_file"):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            content = args.get("content")
            if content is not None:
                text = text + str(content)
    elif action in ("replace_text", "find_and_replace"):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            old = args.get("old_text")
            new = args.get("new_text")
            if old is not None and new is not None:
                text = text.replace(str(old), str(new))
    elif action in ("set_line",):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            line_no = args.get("line") or args.get("line_number")
            content = args.get("content")
            if isinstance(line_no, int) and line_no >= 1 and content is not None:
                lines = text.splitlines(True)
                if lines:
                    endings = []
                    bare = []
                    for ln in lines:
                        if ln.endswith("\r\n"):
                            endings.append("\r\n")
                            bare.append(ln[:-2])
                        elif ln.endswith("\n"):
                            endings.append("\n")
                            bare.append(ln[:-1])
                        elif ln.endswith("\r"):
                            endings.append("\r")
                            bare.append(ln[:-1])
                        else:
                            endings.append("")
                            bare.append(ln)
                    idx = line_no - 1
                    if idx < len(bare):
                        bare[idx] = str(content)
                        text = "".join(b + e for b, e in zip(bare, endings))
    elif action in ("insert_line",):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            line_no = args.get("line") or args.get("line_number")
            content = args.get("content")
            if isinstance(line_no, int) and line_no >= 1 and content is not None:
                nl = "\n"
                if "\r\n" in text:
                    nl = "\r\n"
                elif "\r" in text and "\n" not in text:
                    nl = "\r"
                lines = text.splitlines()
                idx = min(max(line_no - 1, 0), len(lines))
                lines.insert(idx, str(content))
                text = nl.join(lines)
    elif action in ("delete_line",):
        path = args.get("path") or args.get("file_path") or args.get("filename")
        if path == data.get("target"):
            line_no = args.get("line") or args.get("line_number")
            if isinstance(line_no, int) and line_no >= 1:
                nl = "\n"
                if "\r\n" in text:
                    nl = "\r\n"
                elif "\r" in text and "\n" not in text:
                    nl = "\r"
                lines = text.splitlines()
                idx = line_no - 1
                if 0 <= idx < len(lines):
                    del lines[idx]
                    text = nl.join(lines)

